BEGIN;





-- Les id ont été insérés explicitement : on recale les compteurs automatiques
SELECT setval(pg_get_serial_sequence('"user"', 'id'), (SELECT MAX(id) FROM "user"));
SELECT setval(pg_get_serial_sequence('team', 'id'), (SELECT MAX(id) FROM team));
SELECT setval(pg_get_serial_sequence('shift', 'id'), (SELECT MAX(id) FROM shift));

COMMIT;
